package dev.redstoneengineering.physics;
import dev.redstoneengineering.block.*;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.block.state.BlockState;import java.util.*;
/** Bounded 0..15 propagation. Plain cable is two-ended; explicit Junctions provide branching. */
public final class RedstoneCableNetwork{private static final int MAX_NODES=NetworkKernel.MAX_NODES;private RedstoneCableNetwork(){}public static void recompute(ServerLevel l,BlockPos start){Set<BlockPos>nodes=collect(l,start);if(nodes.isEmpty())return;Map<BlockPos,Integer>best=new HashMap<>();PriorityQueue<Node>q=new PriorityQueue<>(Comparator.comparingInt((Node n)->-n.power));for(BlockPos p:nodes){BlockState s=l.getBlockState(p);if(s.getBlock() instanceof RedstoneCableTerminalBlock t&&!s.getValue(RedstoneCableTerminalBlock.OUTPUT_MODE)){int power=t.externalInput(l,p,s);best.put(p,power);q.add(new Node(p,power));}}while(!q.isEmpty()){Node cur=q.poll();if(cur.power<best.getOrDefault(cur.pos,-1))continue;for(Direction d:Direction.values()){BlockPos n=cur.pos.relative(d);if(!nodes.contains(n)||!edgeAllowed(l,cur.pos,n,d))continue;BlockState from=l.getBlockState(cur.pos),to=l.getBlockState(n);int loss=(to.getBlock() instanceof RedstoneSignalCableBlock && !(from.getBlock() instanceof RedstoneCableTerminalBlock&&!from.getValue(RedstoneCableTerminalBlock.OUTPUT_MODE)))?1:0;int next=Math.max(0,cur.power-loss);if(next>best.getOrDefault(n,-1)){best.put(n,next);q.add(new Node(n,next));}}}for(BlockPos p:nodes){BlockState s=l.getBlockState(p);int power=Math.max(0,Math.min(15,best.getOrDefault(p,0)));if(s.getBlock() instanceof RedstoneSignalCableBlock)RedstoneSignalCableBlock.setPower(l,p,power);else if(s.getBlock() instanceof RedstoneCableJunctionBlock)RedstoneCableJunctionBlock.setPower(l,p,power);else if(s.getBlock() instanceof RedstoneCableTerminalBlock t){int shown=s.getValue(RedstoneCableTerminalBlock.OUTPUT_MODE)?power:t.externalInput(l,p,s);BlockState n=s.setValue(RedstoneCableTerminalBlock.POWER,shown);if(n!=s){l.setBlock(p,n,net.minecraft.world.level.block.Block.UPDATE_CLIENTS);if(n.getValue(RedstoneCableTerminalBlock.OUTPUT_MODE)){l.updateNeighborsAt(p,t);l.updateNeighborsAt(p.relative(t.vanillaSide(n)),t);}}}}}
private static Set<BlockPos> collect(ServerLevel l,BlockPos start){Set<BlockPos>v=new LinkedHashSet<>();ArrayDeque<BlockPos>q=new ArrayDeque<>();if(l.hasChunkAt(start)&&allowed(l,start))q.add(start);else for(Direction d:Direction.values()){BlockPos n=start.relative(d);if(l.hasChunkAt(n)&&allowed(l,n))q.add(n);}while(!q.isEmpty()&&v.size()<MAX_NODES){BlockPos p=q.removeFirst();if(!v.add(p))continue;for(Direction d:Direction.values()){BlockPos n=p.relative(d);if(!v.contains(n)&&l.hasChunkAt(n)&&allowed(l,n)&&edgeAllowed(l,p,n,d))q.addLast(n);}}NetworkKernel.recordScan(l,"redstone_cable",v.size(),!q.isEmpty());return v;}
private static boolean edgeAllowed(ServerLevel l,BlockPos a,BlockPos b,Direction d){BlockState sa=l.getBlockState(a),sb=l.getBlockState(b);if(sa.getBlock() instanceof ConnectedCableBlock ca&&(!ca.topologyValid(sa)||!ConnectedCableBlock.connected(sa,d)))return false;if(sb.getBlock() instanceof ConnectedCableBlock cb&&(!cb.topologyValid(sb)||!ConnectedCableBlock.connected(sb,d.getOpposite())))return false;if(sa.getBlock() instanceof RedstoneCableTerminalBlock ta&&ta.cableSide(sa)!=d)return false;if(sb.getBlock() instanceof RedstoneCableTerminalBlock tb&&tb.cableSide(sb)!=d.getOpposite())return false;return true;}
private static boolean allowed(ServerLevel l,BlockPos p){var b=l.getBlockState(p).getBlock();return b instanceof RedstoneSignalCableBlock||b instanceof RedstoneCableJunctionBlock||b instanceof RedstoneCableTerminalBlock;}private record Node(BlockPos pos,int power){}
}
